import { useParams, Link } from "react-router-dom";
import { useState, useEffect } from "react";
import Card from "../components/Card";

export default function RoadmapPage() {
  const { name } = useParams();

  const [domain, setDomain] = useState("");
  const [currentDay, setCurrentDay] = useState(1);
  const [roadmapPlan, setRoadmapPlan] = useState([]);

  const timeline = sessionStorage.getItem("timeline") || "3 months";

  // ✅ LOAD DOMAIN
  useEffect(() => {
    const newDomain = name?.toLowerCase();
    sessionStorage.setItem("selectedDomain", newDomain);
    setDomain(newDomain);
  }, [name]);

  // 🔥 DOMAIN TOPICS
  const topicMap = {
    "web-development": [
      "HTML","CSS","Flexbox","JavaScript","DOM",
      "React","API","Node.js","MongoDB","Project"
    ],
    "ai-and-ml": [
      "Python","NumPy","Pandas","Visualization",
      "ML Basics","Regression","Deep Learning","Project"
    ]
  };

  const topics = topicMap[domain] || ["Basics"];

  // 🚀 FIXED GENERATE PLAN (TIMELINE BASED)
  const generatePlan = () => {
    let totalDays = 90;

    if (timeline.includes("month")) {
      totalDays = parseInt(timeline) * 30;
    } else if (timeline.includes("year")) {
      totalDays = parseInt(timeline) * 365;
    }

    const flatTopics = topics;
    const totalTopics = flatTopics.length;

    const plan = [];

    for (let day = 0; day < totalDays; day++) {
      const start = Math.floor((day * totalTopics) / totalDays);
      const end = Math.floor(((day + 1) * totalTopics) / totalDays);

      let dailyTopics = flatTopics.slice(start, end);

      // ✅ Ensure at least 1 task per day
      if (dailyTopics.length === 0) {
        dailyTopics = [flatTopics[day % totalTopics]];
      }

      plan.push(dailyTopics);
    }

    return plan;
  };

  // ✅ GENERATE PLAN
  useEffect(() => {
    if (domain && timeline) {
      const plan = generatePlan();
      setRoadmapPlan(plan);
      sessionStorage.setItem("roadmapPlan", JSON.stringify(plan));
      sessionStorage.setItem("currentDay", "1");
      setCurrentDay(1);
    }
  }, [domain, timeline]);

  // ✅ LOAD CURRENT DAY
  useEffect(() => {
    const savedDay = parseInt(sessionStorage.getItem("currentDay") || "1");
    setCurrentDay(savedDay);
  }, []);

  const getTasksForDay = (day) => roadmapPlan[day - 1] || [];

  // ✅ PROGRESS (TIMELINE BASED)
  const progress = roadmapPlan.length
    ? (currentDay / roadmapPlan.length) * 100
    : 0;

  return (
    <div className="space-y-8 text-white">
      <Card title="Learning Roadmap">

        {/* HEADER */}
        <h2 className="text-xl font-bold capitalize">
          🚀 {domain?.replaceAll("-", " ")} Roadmap
        </h2>

        {/* PROGRESS */}
        <div className="mt-4">
          <div className="w-full bg-slate-700 h-3 rounded-full">
            <div
              className="h-3 rounded-full"
              style={{
                width: `${progress}%`,
                background: "linear-gradient(90deg, #22c55e, #4f46e5)",
              }}
            />
          </div>
          <p className="text-gray-400 mt-2">
            {Math.floor(progress)}% completed
          </p>
        </div>

        {/* DAY */}
        <h3 className="mt-4">
          Day {currentDay} / {roadmapPlan.length || 1}
        </h3>

        {/* TASKS */}
        <div className="grid gap-3 mt-4">
          {getTasksForDay(currentDay).map((task, i) => (
            <div
              key={i}
              className="p-4 rounded-xl bg-slate-800 border border-slate-700"
            >
              📌 {task}
            </div>
          ))}
        </div>

        {/* NAV */}
        <Link to="/tasks">
          <button className="mt-6 px-6 py-3 bg-teal-500 rounded-xl">
            Go to Tasks →
          </button>
        </Link>

      </Card>
    </div>
  );
}
